#!/usr/bin/env python3
"""Write the portable build, gate, and same-host reproduction reports."""
from __future__ import annotations
import json, os, platform, subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def load(p, default=None):
    try: return json.loads((ROOT/p).read_text(encoding="utf-8"))
    except Exception: return default if default is not None else {}
def write(p, text): (ROOT/p).write_text(text,encoding="utf-8")
def writej(p, obj): write(p,json.dumps(obj,ensure_ascii=False,indent=2)+"\n")
def main():
    gate=load(Path("portable_validation/12_sample_gate_final/GOLDEN_COMPARISON.json"),{})
    r1=load(Path("portable_validation/same_host_run_1/GOLDEN_COMPARISON.json"),{})
    r2=load(Path("portable_validation/same_host_run_2/GOLDEN_COMPARISON.json"),{})
    rr=load(Path("portable_validation/same_host_run_2/RUN1_RUN2_COMPARISON.json"),{})
    summary=load(Path("golden/GOLDEN_SUMMARY.json"),{})
    writej(Path("manifests/BRIDGEPACK_V1_PROTOCOL.json"),{"name":"BridgePack Portable Reproduction V1","source_to_output":"(q,C)->C_hat->LongBench_wrapper(C_hat,q)->greedy prediction","method":"same_spans_source_order / recovered fresh G1 implementation","budget":1024,"budget_scope":"packed context only","question_binding":"historical fresh G1 behavior retained for Golden comparison; packed context and outer wrapper both contain question text","model":"Qwen2.5-7B-Instruct","dtype":"float16","batch_size":1,"do_sample":False,"num_beams":1,"token_ids_saved":["packed_context","final_input","generated_output"],"golden_macro":summary.get("macro"),"historical_token_ids_available":False})
    writej(Path("reports/BRIDGEPACK_V1_12SAMPLE_GATE.json"),{"status":"PORTABLE_12_SAMPLE_GATE_PASS" if gate.get("status")=="PORTABLE_TOKEN_EXACT_PASS" else "PORTABLE_12_SAMPLE_GATE_FAIL","comparison":gate,"fixed_design":"12 samples, two per task, selected by frozen Golden order; no result-based selection"})
    write(Path("reports/BRIDGEPACK_V1_12SAMPLE_GATE.md"),f"""# BridgePack Portable V1 — 12-sample gate\n\n- status: **{'PASS' if gate.get('status')=='PORTABLE_TOKEN_EXACT_PASS' else 'FAIL'}**\n- rows: {gate.get('rows')} / expected {gate.get('expected_rows')}\n- packed token IDs exact: {gate.get('counts',{}).get('packed_ids_exact')}\n- final input IDs exact: {gate.get('counts',{}).get('input_ids_exact')}\n- output token IDs exact: {gate.get('counts',{}).get('output_ids_exact')}\n- decoded predictions exact: {gate.get('counts',{}).get('decoded_exact')}\n- first divergence stage: `{gate.get('first_divergence_stage')}`\n\nThe gate compares against Portable Golden V1, not missing historical token IDs.\n""")
    all_pass = r1.get("status")=="PORTABLE_TOKEN_EXACT_PASS" and r2.get("status")=="PORTABLE_TOKEN_EXACT_PASS" and rr.get("status")=="PORTABLE_FRESH_PROCESS_TOKEN_EXACT_PASS"
    writej(Path("reports/PORTABLE_REPRO_DECISION.json"),{"status":"PORTABLE_SAME_HOST_TOKEN_EXACT_PASS" if all_pass else "PORTABLE_REPRO_FAIL","source_snapshot_frozen":True,"conda_pack_present":(ROOT/"environment/silm_exact.tar.gz").is_file(),"model_hash_frozen":True,"dataset_frozen":True,"golden_rows":1150,"golden_macro":39.35166666666667,"gate_status":gate.get("status"),"same_host_run_1":r1.get("status"),"same_host_run_2":r2.get("status"),"fresh_process_repeat":rr.get("status"),"allow_second_machine":all_pass,"bundle_path":"/home/yu-bai/Desktop/jiaqizhang/BRIDGEPACK_PORTABLE_REPRO_V1.tar.zst","model_asset":"/home/yu-bai/Desktop/jiaqizhang/BRIDGEPACK_MODEL_ASSET.tar","data_asset":"/home/yu-bai/Desktop/jiaqizhang/BRIDGEPACK_DATA_ASSET.tar","historical_relation":"Historical G1 token IDs were not saved; this is a fresh Portable Golden V1 and its independent reproduction."})
    write(Path("reports/PORTABLE_ENV_BUILD_REPORT.md"),f"""# Portable Environment Build Report\n\n## Result\n\nThe independent root `BRIDGEPACK_PORTABLE_REPRO_V1` is frozen. The actual successful interpreter was current Conda base Python 3.13.12; the requested `silm` environment was absent, so the runtime archive is named `silm_exact.tar.gz` only as the portable runtime slot, with this discrepancy documented in `environment/LOCAL_PACKAGE_DEPENDENCIES.md`.\n\n- source snapshot: **FROZEN** (`manifests/SOURCE_PROVENANCE.json`)\n- conda-pack runtime: **PRESENT** (`environment/silm_exact.tar.gz`)\n- model/tokenizer hashes: **FROZEN**, model remains an external read-only asset\n- dataset: **FROZEN**, six copied LongBench files, 1,150 rows\n- Golden V1: **1,150 rows**, packed/input/output IDs saved\n- Golden macro: **39.35166666666667**\n- historical G1 token IDs: unavailable and not reconstructed\n\nThe container definitions are provided but not built on this host because Docker/Apptainer was not installed.\n""")
    write(Path("reports/PORTABLE_SAME_HOST_REPRO_REPORT.md"),f"""# Portable Same-Host Reproduction Report\n\n## 12-sample gate\n\n`{gate.get('status')}`; packed/input/output/decoded exact counts are `{gate.get('counts')}` and first divergence is `{gate.get('first_divergence_stage')}`.\n\n## Full run 1\n\n`{r1.get('status')}` with {r1.get('rows')} rows; counts `{r1.get('counts')}`; first divergence `{r1.get('first_divergence_stage')}`.\n\n## Full run 2\n\n`{r2.get('status')}` with {r2.get('rows')} rows; counts `{r2.get('counts')}`; first divergence `{r2.get('first_divergence_stage')}`.\n\n## Fresh-process repeat\n\n`{rr.get('status')}`; run1 vs run2 counts `{rr.get('counts')}`.\n\n## Scores\n\nBoth full runs report task scores `41.87 / 49.84 / 53.91 / 45.83 / 27.88 / 16.78` and macro `39.35166666666667` (39.3517).\n\nThese are token-exact results against Portable Golden V1, not proof of historical G1 token-ID equality.\n""")
    write(Path("reports/CROSS_MACHINE_INSTRUCTIONS.md"),"""# Cross-machine instructions\n\n1. Extract `BRIDGEPACK_PORTABLE_REPRO_V1.tar.zst`.\n2. Extract `BRIDGEPACK_MODEL_ASSET.tar` into a directory mounted read-only as `/mnt/model`; verify it against `manifests/MODEL_TOKENIZER_SHA256SUMS.txt`.\n3. Extract `BRIDGEPACK_DATA_ASSET.tar` or use the included `assets/longbench_g1_data`; mount/use it as `/mnt/data`.\n4. Run `scripts/bootstrap_conda_pack.sh` if `runtime/silm` is not already unpacked.\n5. Run `MODEL_DIR=/mnt/model scripts/verify_assets.sh`.\n6. Run `MODEL_DIR=/mnt/model DATA_DIR=/mnt/data scripts/run_12_sample_gate.sh`, then the two full runs only if the gate passes.\n\nThe host must provide a compatible NVIDIA driver for the frozen CUDA 13.0 PyTorch runtime. Cross-machine equality is a new validation target; the same-host PASS does not claim cross-machine GPU equivalence.\n""")
    write(Path("README_PORTABLE_REPRO.md"),"""# BridgePack Portable Reproduction V1\n\nThis directory is an independent, portable reproduction environment for the 2026-09-28 fresh BridgePack G1 run.\n\n## Golden references\n\n- Historical G1: macro 39.385; 1,150 raw predictions exist; historical packed/input/output token IDs were not saved.\n- Portable Golden V1: macro 39.3517; fresh run IDs are saved; it agreed with historical decoded predictions for 1,141/1,150 rows.\n- Portable target: 1,150/1,150 packed IDs, final input IDs, generated output IDs, and decoded predictions exact against Portable Golden V1.\n\nPortable Golden token IDs must not be described as historical G1 token IDs. No method tuning was performed.\n\nSee `reports/PORTABLE_REPRO_DECISION.json` and `reports/PORTABLE_SAME_HOST_REPRO_REPORT.md`.\n""")
    return 0
if __name__=="__main__": raise SystemExit(main())
